const CACHE='hocco-message-shell-v81';
const SHELL=["/","/index.html","/cliente/","/cliente/index.html","/cliente/entry.mjs","/ir-alem/","/ir-alem/index.html","/ir-alem/app.mjs","/style.css","/theme.css","/streaming.css","/theme.js","/cinema.css","/refinement.css","/experience.mjs","/config.mjs","/payment-state.mjs","/tracking-progress.mjs","/participation-layout.mjs","/sponsor-wizard.mjs","/pix-checkout.mjs","/avatars.mjs","/assets/figurantes-portraits-v4.webp","/app.mjs","/customer-sync.mjs","/reactivation.mjs","/live-availability.mjs","/cinema.mjs","/official-poster.mjs","/cinema-shell.mjs","/location.mjs","/city-offers.mjs","/navigation-ui.mjs","/carousel-advisory.mjs","/community-carousel.mjs","/community-reactions.mjs","/purchase-draft.mjs","/support.mjs","/pwa.mjs","/opening-brand.mjs","/policies.mjs","/manifest.webmanifest","/assets/hocco-message-icon.svg","/assets/hocco-butterfly-damaged-v1.svg","/assets/hocco-launch-v1.svg","/assets/hocco-launch-v1-192.png","/assets/hocco-launch-v1-512.png"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||url.pathname.startsWith('/api/')||url.pathname.endsWith('.mp3')||event.request.headers.has('range'))return;if(/^\/(?:controle|equipe)(?:\/|$)/.test(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const clone=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,clone))}return response}).catch(()=>caches.match(event.request).then(response=>response||(event.request.mode==='navigate'?caches.match('/index.html'):Response.error()))))});

self.addEventListener('push',event=>{event.waitUntil((async()=>{let data={};try{data=event.data?.json()||{}}catch{}let url=new URL('/#inicio',self.location.origin);try{const candidate=new URL(data.url||'/#inicio',self.location.origin);if(candidate.origin===self.location.origin&&!/^\/(?:controle|equipe)(?:\/|$)/.test(candidate.pathname))url=candidate}catch{}await self.registration.showNotification(String(data.title||'HOCCO Reality').slice(0,80),{body:String(data.body||'O HOCCO continua. Volte ao Reality.').slice(0,260),icon:'/assets/hocco-launch-v1-192.png',badge:'/assets/hocco-butterfly-damaged-v1.svg',tag:/^[A-Za-z0-9_-]{1,32}$/.test(data.tag||'')?data.tag:'hocco-reality-return',renotify:false,data:{url:url.href,id:data.id||null}})})())});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{let url=new URL('/#inicio',self.location.origin);try{const target=new URL(event.notification.data?.url||'/#inicio',self.location.origin);if(target.origin===self.location.origin&&!/^\/(?:controle|equipe)(?:\/|$)/.test(target.pathname))url=target}catch{}const windows=await self.clients.matchAll({type:'window',includeUncontrolled:true});const client=windows.find(c=>{try{return new URL(c.url).origin===self.location.origin&&!/^\/(?:controle|equipe)(?:\/|$)/.test(new URL(c.url).pathname)}catch{return false}});if(client){await client.navigate(url.href);return client.focus()}return self.clients.openWindow(url.href)})())});
